export function getSectorNewsFromMatrix(year, sector, direction) {
    const yr = Number(year) || 2015;
    const dir = direction === 'DOWN' ? 'DOWN' : 'UP';
    
    // 섹터 매칭
    let matchedSector = '반도체/IT';
    const s = (sector || '').trim();
    if (s.includes('반도체') || s.includes('IT')) matchedSector = '반도체/IT';
    else if (s.includes('2차전지') || s.includes('배터리')) matchedSector = '2차전지';
    else if (s.includes('바이오') || s.includes('제약') || s.includes('헬스')) matchedSector = '바이오';
    else if (s.includes('자동차') || s.includes('모빌리티')) matchedSector = '자동차';
    else if (s.includes('인터넷') || s.includes('게임') || s.includes('플랫폼')) matchedSector = '인터넷/게임';
    else if (s.includes('엔터') || s.includes('미디어') || s.includes('콘텐츠')) matchedSector = '엔터/미디어';
    else if (s.includes('화학') || s.includes('정유') || s.includes('에너지')) matchedSector = '화학/에너지';
    else if (s.includes('조선') || s.includes('방산') || s.includes('우주')) matchedSector = '조선/방산';
    else if (s.includes('철강') || s.includes('소재') || s.includes('비철')) matchedSector = '철강/소재';
    else if (s.includes('금융') || s.includes('은행') || s.includes('증권') || s.includes('지주')) matchedSector = '금융/지주';
    else if (s.includes('소비재') || s.includes('뷰티') || s.includes('유통') || s.includes('화장품')) matchedSector = '소비재/뷰티';
    else if (s.includes('음식료') || s.includes('푸드') || s.includes('식품')) matchedSector = '음식료';
    else if (s.includes('통신') || s.includes('유틸리티')) matchedSector = '통신/유틸리티';
    else if (s.includes('건설') || s.includes('인프라')) matchedSector = '건설/인프라';

    const yearData = YEARLY_SECTOR_NEWS_MATRIX[yr] || YEARLY_SECTOR_NEWS_MATRIX[2015];
    const secData = yearData[matchedSector] || yearData['반도체/IT'];
    return secData[dir] || secData['UP'];
}
